CREATE TABLE IF NOT EXISTS public.subcontrato_portal_intentos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, token_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS subcontrato_portal_intentos_hash_fecha_idx ON public.subcontrato_portal_intentos(token_hash,created_at DESC); ALTER TABLE public.subcontrato_portal_intentos ENABLE ROW LEVEL SECURITY;;
